style.css:
@-moz-document domain("roblox.com") {
/* Fake Robux: Muestra 999,999 Robux en la barra superior */
    .rbx-text-navbar-right[title*="Robux"],
    .rbx-text-navbar {
        font-size: 16px !important;
        font-weight: bold !important;
        color: #FFD700 !important;
    }
    .rbx-text-navbar-right[title*="Robux"]::after {
        content: " 999,999+" !important; /* Falso saldo de Robux */
        font-size: 16px !important;
        font-weight: bold !important;
        color: #FFD700 !important;
    }
    
    /* Fake Buy: Hace que todos los botones de compra parezcan accesibles */
    .purchase-button,
    .btn-buy {
        background: #00FF00 !important; /* Color verde como si fuera gratis */
        color: white !important;
        font-weight: bold;
        border-radius: 5px;
        text-transform: uppercase;
    }
    .purchase-button:hover,
    .btn-buy:hover {
        background: #009900 !important;
    }
    
    /* Fake Purchases: Hace que los artículos parezcan comprados */
    .purchase-button,
    .btn-buy {
        pointer-events: none !important; /* Evita la compra real */
    }
    .purchase-button::after,
    .btn-buy::after {
        content: "✓ Comprado" !important; /* Muestra como si estuviera comprado */
        color: #FFD700 !important;
        font-weight: bold !important;
    }
}
